styles:
.page-post .post-head { padding-top: clamp(120px, 17vh, 200px); padding-bottom: clamp(28px, 5vw, 56px); }
.page-post .post-head__inner { max-width: 820px; margin-inline: auto; }
.page-post .post-eyebrow { margin-bottom: 18px; }
.page-post .post-title {
  font-family: var(--font-display);
  font-size: clamp(32px, 5.2vw, 64px);
  line-height: 1.12; color: var(--grey-700); letter-spacing: -0.01em;
}
.page-post .post-meta {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px;
  margin-top: clamp(20px, 3vw, 30px);
  font-size: clamp(14px, 1vw, 16px); color: var(--grey-500);
}
.page-post .post-meta__author { color: var(--grey-900); }
.page-post .post-meta .dot { width: 4px; height: 4px; border-radius: 50%; background: var(--grey-300); flex-shrink: 0; }

.page-post .post-cover {
  max-width: 900px; margin: clamp(28px, 5vw, 56px) auto 0;
  border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt);
}
.page-post .post-cover img { width: 100%; height: auto; object-fit: cover; }

.page-post .post-body { max-width: 720px; margin-inline: auto; padding-block: clamp(40px, 6vw, 72px); }
.page-post .post-body p {
  font-family: var(--font-body); color: var(--grey-700);
  font-size: clamp(17px, 1.25vw, 19px); line-height: 1.95;
  margin-bottom: 1.5em;
}
.page-post .post-body p:last-child { margin-bottom: 0; }
.page-post .post-body .lead { color: var(--grey-900); }
.page-post .post-body ol.post-list {
  list-style: none; counter-reset: pl;
  margin: 0 0 1.9em; padding: 0;
  display: grid; gap: 16px;
}
.page-post .post-body ol.post-list li {
  position: relative; padding: 20px 24px; padding-left: 62px;
  border: 1px solid var(--line); border-radius: var(--radius);
  font-size: clamp(16px, 1.15vw, 18px); line-height: 1.7; color: var(--grey-700);
}
.page-post .post-body ol.post-list li::before {
  counter-increment: pl; content: counter(pl);
  position: absolute; left: 20px; top: 18px;
  width: 28px; height: 28px; border-radius: 50%;
  background: var(--red); color: #fff;
  font-family: var(--font-display); font-size: 15px;
  display: grid; place-items: center;
}
.page-post .post-body ol.post-list li strong { color: var(--grey-900); font-weight: 400; }

.page-post .post-back {
  max-width: 720px; margin: 0 auto; padding-bottom: clamp(60px, 9vw, 120px);
}
.page-post .post-back a {
  display: inline-flex; align-items: center; gap: 12px;
  border: 1px solid var(--grey-300); border-radius: 999px;
  padding: 11px 22px; font-size: 16px; color: var(--grey-900);
  transition: border-color .3s var(--ease), color .3s var(--ease);
}
.page-post .post-back a:hover { border-color: var(--red); color: var(--red); }
.page-post .post-back a .arrow { color: var(--red); display: grid; place-items: center; }

@media (max-width: 760px) {
  .page-post .post-body ol.post-list li { padding-left: 58px; }
}
